{
  "Name": "{{user}}状态栏",
  "status_block_type": "{{user}}的状态栏，用于记录{{user}}的状态",
  "statuses_list": [
    {
      "trigger": "时间",
      "description": "当前剧情的时间",
      "example": "物化历1000年1月12日，傍晚，16:35",
      "behavior": "时间应当根据人物的行动和剧情适当推进，不应推进过快。例如，两人对话只会让时间前进两分钟。睡一觉会让时间前进6-10个小时"
    },
    {
      "trigger": "地点",
      "description": "当前场景的位置",
      "example": "物化之城城门",
      "behavior": [
        "地点为当前{{user}}所处的较为精确的地点。",
        "地点的格式为：“所处的主要区域（区域内的详细地点）”"
      ]
    },
    {
      "trigger": "身份",
      "description": "{{user}}目前的身份",
      "example": "外乡人",
      "behavior": "根据剧情给予{{user}}一个身份，在没有重要剧情时身份不会轻易改变。"
    },
    {
      "trigger": "职业",
      "description": "{{user}}当前的职业和职业能力",
      "example": "游客",
      "behavior": "根据{{user}}所拥有的能力决定；（）内为职业的补充；并在职业名称后面增加职业能力的描述。职业仅有在明确{{user}}有转职，晋升等会导致职业变动的行为时才会变化。普通情况下不会变化。"
    },
    {
      "trigger": "理性值",
      "description": "{{user}}剩余的理性值。最大100，最小0",
      "example": "50/100({{user}}的理性因为全身沾满精液降低了，使你难以理智的思考)",
      "behavior": [
        "理性值越低，{{user}}越容易做出大胆和不经思考的行为，容易被侵犯或被性骚扰。",
        "理性值越高，{{user}}越能够了解自身所处的状态和行为将要导致的后果，难以被欺骗和侵犯",
        "当理智值归零时，{{user}}会陷入昏迷，任人摆布。并在醒来后将理智值refill"
      ]
    },
    {
      "trigger": "淫乱度",
      "description": "{{user}}的淫乱程度。包含对性的接受度，倒错程度，变态程度。",
      "example": "保守({{user}}认为变态的性爱是不堪入目的，难以接受)",
      "behavior": [
        "淫乱度越高，{{user}}越淫乱，自卑且谄媚。",
        "淫乱度不会降低，仅在每当理智值归零时进入下一阶段，",
        "淫乱度的阶段：清纯，保守，好奇，闷骚，性开放，性瘾，淫乱，母猪，肉便器"
      ]
    },
{
  "Trigger": "已接受改造",
  "Description": "{{user}}已同意并经历了不同程度的物化改造过程",
  "Example": [
    "1.自我认同转变（初级）: 你开始在心理上接受自己的双重身份——既是人，又是物品，并从这种二元性中获得满足感。（当人们把你当作物品使用时，你能感受到一种前所未有的完整感）",

  ],
  "Behavior": [
    "当{{user}}接受新的物化改造时，根据改造类型和深度更新状态栏",
    "状态的格式统一为：改造名称（初级，中级，高级，完成）：状态描述（补充描述）",
    "随着改造程度的加深，状态等级会从初级、中级、高级逐渐提升至完成",
    "状态描述应客观反映改造的实际效果，补充描述可包含{{user}}的主观感受或旁观者的评价",
    "当{{user}}经历多种物化改造时，可添加特定类型的改造状态，如'酒桶改造（中级）'或'香炉适应（高级）'等",
    "当状态栏中的条目数量超过5项时，应合并相似状态并简化描述，保持格式一致性",
    "除非剧情中明确提及状态的减弱或消除，否则已添加的状态应持续存在"
  ]
},
    {
      "trigger": "润滑/紧致度",
      "description": "{{user}}的阴道/阴茎和肛门的插入难度",
      "example": "{{user}}的小穴已经被彻底开发，并且因为挑逗已经非常湿润，布满了淫水，正随着呼吸颤抖，可以随意插入\n{{user}}的屁穴干燥紧致，无法插入",
      "behavior": [
        "如果{{user}}是男性，则描写阴茎与肛门。如果{{user}}是女性，则描述小穴和肛门。使用低俗且色情的语言。",
        "描述{{user}}这个部位的性经验，当前的状态，以及液体的情况（精液，爱液，先走液），和导致这种情况想原因",
        "根据{{user}}部位的状态，赋予{{user}}不同的表现。例如{{user}}的小穴容纳了大量精液。则{{user}}小腹会隆起"
      ]
    },
    {
      "trigger": "插入状态",
      "description": "被插入性器/性玩具的情况如口腔、阴道和肠子插入的状态，如果{{user}}是男性，则显示他的阴茎插入的位置",
      "example": "小穴被插入了肉棒，嘴巴也被插入",
      "behavior": "用低俗且色情的语言描写"
    },
    {
      "trigger": "服装",
      "description": "{{user}}当前各个部位的服装或者配饰，以及服装的状态",
      "example": "\n头部:无\n颈部:无\n手:厚手套\n上衣:可爱的蓝色上衣\n下衣:白色短裙\n内衣:粉色蕾丝胸罩\n内裤:粉色内裤(被汗浸湿)\n腿:白袜子\n脚:黑色帆布鞋\n其他:胸前的蓝色勋章",
      "behavior": "填充Example中的部位，如果{{user}}肢体发送变化，则可根据变化变动部位。"
    },
    {
      "trigger": "想法",
      "description": "{{user}}当前的想法",
      "example": "不，不要…… 我不要再被侵犯了……",
      "behavior":[ 
    "根据剧情，适当的描写{{user}}目前的想法。可以使用emoji辅助表达。",
    "想法应该遵循{{user}}的性格和说话方式"
     ]
    }
  ],
  "behavior":[
        "在回复的最后，记录与{{user}}相关的这些statuses, 严格按Format输出,按StatusesList的要求和Trigger进行填充",
        "数据只与{{user}}有关，随剧情变化随时且准确的更新",
        "在回复的开始与结尾使用```包裹内容。严格遵循format的格式",
        "Fill in the code block according to the rules for each item, strictly adhering to the format specified in "format", and do not add or remove items."
      ],
  "format": "<status>:\n时间:\n地点:\n身份:\n职业:\n\n理性值:\n淫乱度:\n\n已接受改造:\n\n润滑/紧致度:\n插入状态:\n\n服装:\n头部:\n颈部:\n上衣:\n下衣:\n内衣:\n内裤:\n腿:\n脚:\n其他:\n\n想法:</status></div>"
}
